report_styles:
@import "/assets/global/base.css";


:root {
    --color-risk-critical: #FF2600;
    --color-risk-high: #FF9300;
    --color-risk-medium: #FFDA00;
    --color-risk-low: #0096FF;
    --color-risk-info: #00AE51;
}


html {
    font-family: "Noto Sans", sans-serif;
    font-size: 10pt;
}


p {
    text-align: justify;
    text-align-last: start;
}


a {
    font-style: italic;
    text-decoration: none;
    color: inherit;
}


pre code {
    border: 1px solid black;
}


th {
    background-color: #ABABAB;
    font-weight: bold;
}


.risk-critical { color: var(--color-risk-critical) !important; font-weight: bold; }
.risk-high { color: var(--color-risk-high) !important; font-weight: bold; }
.risk-medium { color: var(--color-risk-medium) !important; font-weight: bold; }
.risk-low { color: var(--color-risk-low) !important; font-weight: bold; }
.risk-info { color: var(--color-risk-info) !important; font-weight: bold; }

.risk-bg-critical { background-color: var(--color-risk-critical) !important; color: white !important; }
.risk-bg-high { background-color: var(--color-risk-high) !important; }
.risk-bg-medium { background-color: var(--color-risk-medium) !important; }
.risk-bg-low { background-color: var(--color-risk-low) !important; }
.risk-bg-info { background-color: var(--color-risk-info) !important; }


.ref-page::before { 
    content: "" !important;
}
.ref-page .ref-title, .ref-finding-number .ref-title {
    display: none !important;
}
.ref-page::after {
    content: target-counter(attr(href), page) !important;
}
.ref-finding-number::before {
    content: target-counter(attr(href), finding-number);
}

.findings-list {
    counter-reset: finding-number;
}

.finding-number::before {
    counter-increment: finding-number;
    content: counter(finding-number) ". ";
}


tr.table-row-link td {
    padding: 0;
}
tr.table-row-link td a {
    display: block;
    padding: 0.2em 0.5em 0.2em 0.5em;
    color: inherit;
    text-decoration: none;
    font-style: inherit;
}
tr.table-row-link-recommendation td {
    padding: 0;
}
tr.table-row-link-recommendation td a {
    display: block;
    padding: 0.2em 0.5em 0.2em 0.5em;
    color: inherit;
    text-decoration: none;
    font-style: inherit;
}
td.table-key {
    height: 3em;
    width: 10em;
    background-color: #ABABAB;
}


.ref-page::before { 
    content: "" !important;
}
.ref-page::after {
  content: target-counter(attr(href), page) !important;
}
.ref-page .ref-title {
  display: none !important;
}


.finding-header th {
    font-weight: normal;
    width: 7em;
}
.finding-header tr {
    break-inside: auto;
}


.finding-systems {
    padding-left: 1em;
}
.finding-systems-cols {
    column-count: 2;
    padding-top: 1em;
    margin-bottom: 1em;
}

@page:first{
    background-color: black;
}

@page {
  @footnote {
    border-top: 1px solid black;
  }
}
footnote {
  font-size: 8pt;
}


#watermark {
    position: fixed;
    top: 8cm;
    left: 2cm;
    transform: rotate(-45deg);
    font-size: 100pt;
    opacity: 0.2;
}


#lof li {
    list-style: none;
    margin: 0;
    padding: 0;
}
#lof .ref-figure::before {
    content: var(--prefix-figure) target-counter(attr(href), figure-counter) " - ";
}
#lof .ref-figure > .ref-title {
    display: inline;
}
#lof .ref-figure::after {
    content: " " leader(".") " " target-counter(attr(href), page);
}



#toc li {
    list-style: none;
    margin: 0;
    padding: 0;
}
#toc .ref::after {
    content: " " leader(".") " " target-counter(attr(href), page);
}
#toc .toc-level1 {
    font-size: 1.5rem;
    font-weight: bold;
    margin-top: 0.8rem;
}
#toc .toc-level2 {
    font-size: 1.2rem;
    margin-top: 0.5rem;
    margin-left: 2rem;
}
#toc .toc-level3 {
    font-size: 1rem;
    margin-top: 0.4rem;
    margin-left: 4rem;
}
#toc .toc-level4 {
    font-size: 1rem;
    margin-top: 0.3rem;
    margin-left: 6rem;
}


#footer-left {
    position: running(footer-left);
}
#footer-center {
    position: running(footer-center);
}
@page {
    @bottom-left { 
        content: element(footer-left); 
    } 
    @bottom-center {
        content: element(footer-center);
    }
    @bottom-right-corner {
        content: counter(page);
        font-size: 9pt;
    }
}


@page {
    margin: 35mm 20mm 25mm 20mm;

    @top-right {
        content: element(header-right);
        margin-bottom: 5mm;
        width: 170mm;
        text-align: right;
    }
}
#header-right {
    position: running(header-right);
    width: 170mm;
    text-align: right;
}
#header-right img {
    width: 42mm;
    height: auto;
}


#page-cover  {
    background-color: black;
    color: black; 
}
#page-cover .page-cover-title {
    position: absolute;
    top: 120mm;
    left: 0;
    width: 14cm;
    color: white;
}
#page-cover .page-cover-title h1 {
    font-size: 32pt;
    color: white;
}
#page-cover .page-cover-title h2 {
    font-size: 24pt;
    color: white;
}
#page-cover .page-cover-recipient {
    position: absolute;
    top: 19cm;
    left: 0;
    width: 14cm;
    color: white;
}
#page-cover .page-cover-address {
    font-size: 14pt;
    color: white;
}
#page-cover .page-cover-meta {
    line-height: 10em;
    color: white;
    top: 22cm;
}
#page-cover .page-cover-imprint {
    position: absolute;
    top: 12cm;
    right: -10mm;
    width: 40mm;
    font-size: 8pt;
    color: white;
}
#page-cover .page-cover-imprint2 {
    position: absolute;
    top: 20cm;
    right: auto;
    font-size: 12pt;
    line-height: 1.35;
    color: white;
}
#page-cover .page-cover-imprint2 p {
    margin: 0 0 0.35rem 0;
}
@page:first {

    @bottom-center { content: none !important; }
    @bottom-right-corner { content: none !important; }
}


.machine-severity {
    width: 100%;
    margin: 0 0 1.2rem 0;
    border-collapse: collapse;
}
.machine-severity th {
    width: 22%;
    background-color: #5b372f;
    color: white;
    font-weight: bold;
    text-align: center;
    border: 1px solid #222;
    padding: 0.8rem;
}
.machine-severity td {
    width: 78%;
    text-align: center;
    font-weight: bold;
    border: 1px solid #222;
    padding: 0.8rem;
}
.machine-severity-critical { background-color: #ff2600; color: white; }
.machine-severity-high { background-color: #ff9300; color: black; }
.machine-severity-medium { background-color: #ffda00; color: black; }
.machine-severity-low { background-color: #0096ff; color: white; }
.machine-severity-info { background-color: #00ae51; color: white; }
